// The parabola y^2 = 4x with its focus and its directrix.
//
// A two-argument size call bounds the output under Asymptote's default keepAspect
// and does not scale labels, so the compiler decides the box. This declaration is
// restated from a real compile by `npm run content:figures -- --record-aspect-ratios`.
import graph;
size(261,247);
draw(graph(new real(real t){return t*t/4;},-3.5,3.5));
draw((-1,3.6)--(-1,-3.6),dashed);
dot((0,0), black+2.5pt);
dot((1,0), black+3pt);
label("vertex $(0,0)$",(-0.5,-0.6),SW);
label("focus $(1,0)$",(1.5,0.4),NE);
label("directrix $x=-1$",(-1.2,3.3),NW);
label("$y^{2}=4x$",(2.6,-2.1),SE);

// The ellipse x^2/25 + y^2/9 = 1 with its axes and foci.
//
// A two-argument size call bounds the output under Asymptote's default keepAspect
// and does not scale labels, so the compiler decides the box. This declaration is
// restated from a real compile by `npm run content:figures -- --record-aspect-ratios`.
import graph;
size(301,141);
draw(ellipse((0,0),5,3));
draw((-5,0)--(5,0),dashed);
draw((0,-3)--(0,3),dashed);
dot((5,0), black+2.5pt);
dot((-5,0), black+2.5pt);
dot((4,0), black+3pt);
dot((-4,0), black+3pt);
label("vertex $(5,0)$",(5,0.4),NE);
label("focus $(4,0)$",(4,-0.5),SE);
label("$a=5$",(0,-0.5),S);
label("$b=3$",(0.6,0),E);

// The hyperbola x^2/9 - y^2/16 = 1 with vertices, foci, asymptotes.
//
// A two-argument size call bounds the output under Asymptote's default keepAspect
// and does not scale labels, so the compiler decides the box. This declaration is
// restated from a real compile by `npm run content:figures -- --record-aspect-ratios`.
import graph;
size(301,429);
draw(graph(new real(real t){return 4*sqrt(1+t*t);},-2,2));
draw(graph(new real(real t){return -4*sqrt(1+t*t);},-2,2));
draw(graph(new real(real t){return (4.0/3)*t;},-2,2),dashed);
draw(graph(new real(real t){return -(4.0/3)*t;},-2,2),dashed);
dot((3,0), black+2.5pt);
dot((-3,0), black+2.5pt);
dot((5,0), black+3pt);
dot((-5,0), black+3pt);
label("vertex $(3,0)$",(3,0.5),SE);
label("focus $(5,0)$",(5,0.5),NE);
label("asymptote",(2.2,3.1),NE);
label("asymptote",(-2.2,-3.1),SW);

// A circle recovered from a general equation by completing the square.
//
// A two-argument size call bounds the output under Asymptote's default keepAspect
// and does not scale labels, so the compiler decides the box. This declaration is
// restated from a real compile by `npm run content:figures -- --record-aspect-ratios`.
size(301,301);
draw(circle((2,2),sqrt(8)));
draw((-1.6,0)--(5.2,0),Arrow);
draw((0,-1.6)--(0,5.2),Arrow);
dot((2,2), black+3pt);
dot((2-sqrt(8),2), black+2.5pt);
label("center $(2,2)$",(2,2.4),NE);
label("$r=\sqrt{8}$",(0.3,1.0),SW);
label("$(x-2)^{2}+(y-2)^{2}=8$",(2,-1.0),S);
